def now_utc() -> str:
    """Return the current UTC timestamp as an ISO-8601 string."""
    return datetime.now(timezone.utc).isoformat()


def read_json(path: Path) -> Dict[str, Any]:
    """Read and decode a UTF-8 JSON file."""
    with path.open("r", encoding="utf-8") as f:
        return json.load(f)


def write_json(path: Path, obj: Dict[str, Any]) -> None:
    """Write a dictionary as deterministic, human-readable JSON.
    
    Parent directories are created automatically and non-standard scalar values are
    normalised through :func:`json_safe`."""
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("w", encoding="utf-8") as f:
        json.dump(obj, f, indent=2, sort_keys=True, default=json_safe)


def json_safe(x: Any) -> Any:
    """Convert common pandas/NumPy scalar values into JSON-safe values.
    
    NaN-like values are converted to ``None``. NumPy scalar types are converted to
    their corresponding Python scalar types when NumPy is available."""
    try:
        import numpy as np
        if isinstance(x, (np.integer,)):
            return int(x)
        if isinstance(x, (np.floating,)):
            if math.isnan(float(x)):
                return None
            return float(x)
        if isinstance(x, (np.bool_,)):
            return bool(x)
    except Exception:
        pass
    if isinstance(x, float) and math.isnan(x):
        return None
    if pd.isna(x):
        return None
    return str(x)


def parse_bool_series(s: pd.Series) -> pd.Series:
    """Normalise a pandas Series to pandas' nullable Boolean dtype.
    
    Recognised textual true/false representations are converted explicitly;
    unrecognised or missing values become ``pd.NA``."""
    if s is None:
        return pd.Series(dtype="boolean")
    if s.dtype == bool:
        return s.astype("boolean")
    return s.map(lambda v: (
        True if str(v).strip().lower() in {"true", "1", "yes", "y"} else
        False if str(v).strip().lower() in {"false", "0", "no", "n"} else
        pd.NA
    )).astype("boolean")


def safe_float(v: Any) -> Optional[float]:
    """Return ``v`` as ``float`` when possible, otherwise ``None``."""
    try:
        if v is None or pd.isna(v):
            return None
        return float(v)
    except Exception:
        return None


def mean_numeric(df: pd.DataFrame, col: str) -> Optional[float]:
    """Return the mean of a numeric column, ignoring invalid values."""
    if col not in df.columns:
        return None
    vals = pd.to_numeric(df[col], errors="coerce")
    if vals.notna().sum() == 0:
        return None
    return float(vals.mean())


def median_numeric(df: pd.DataFrame, col: str) -> Optional[float]:
    """Return the median of a numeric column, ignoring invalid values."""
    if col not in df.columns:
        return None
    vals = pd.to_numeric(df[col], errors="coerce")
    if vals.notna().sum() == 0:
        return None
    return float(vals.median())


def std_numeric(df: pd.DataFrame, col: str) -> Optional[float]:
    """Return the sample standard deviation of a numeric column.
    
    ``None`` is returned when the column is absent or fewer than two valid values
    are available."""
    if col not in df.columns:
        return None
    vals = pd.to_numeric(df[col], errors="coerce")
    if vals.notna().sum() <= 1:
        return None
    return float(vals.std())


def rate_bool(df: pd.DataFrame, col: str) -> Optional[float]:
    """Return the fraction of valid values in a column that evaluate to true."""
    if col not in df.columns:
        return None
    vals = parse_bool_series(df[col])
    valid = vals.dropna()
    if len(valid) == 0:
        return None
    return float(valid.mean())


def rate_match_or_bool(df: pd.DataFrame, bool_col: str, value_col: str, query_value_in: Any) -> Optional[float]:
    """Return a same-* rate from a boolean indicator if present, else compare value_col to query value."""
    rb = rate_bool(df, bool_col)
    if rb is not None:
        return rb
    if value_col not in df.columns or query_value_in in (None, ""):
        return None
    vals = df[value_col].dropna().astype(str).str.strip().str.lower()
    if len(vals) == 0:
        return None
    q = str(query_value_in).strip().lower()
    return float((vals == q).mean())


def non_missing_rate(df: pd.DataFrame, col: str) -> Optional[float]:
    """Return the fraction of non-missing values in a dataframe column."""
    if col not in df.columns:
        return None
    return float(df[col].notna().mean()) if len(df) else None


def unique_count(df: pd.DataFrame, col: str) -> Optional[int]:
    """Return the number of distinct non-null string values in a column."""
    if col not in df.columns:
        return None
    return int(df[col].dropna().astype(str).nunique())


def most_common_value(df: pd.DataFrame, col: str) -> Optional[str]:
    """Return the most frequent non-null value in a column as a string."""
    if col not in df.columns or len(df) == 0:
        return None
    vc = df[col].dropna().astype(str).value_counts()
    if vc.empty:
        return None
    return str(vc.index[0])


def entropy_from_counts(counts: Iterable[int]) -> Optional[float]:
    """Compute Shannon entropy in bits from positive integer counts."""
    counts = [int(c) for c in counts if c and c > 0]
    total = sum(counts)
    if total <= 0:
        return None
    ent = 0.0
    for c in counts:
        p = c / total
        ent -= p * math.log(p, 2)
    return float(ent)


def normalized_entropy(df: pd.DataFrame, col: str) -> Optional[float]:
    """Return normalised categorical entropy for a dataframe column.
    
    The result lies between 0 and 1 when calculable, where lower values indicate a
    more concentrated distribution and higher values indicate greater diversity."""
    if col not in df.columns or len(df) == 0:
        return None
    vc = df[col].dropna().astype(str).value_counts()
    if vc.empty:
        return None
    ent = entropy_from_counts(vc.values)
    if ent is None:
        return None
    max_ent = math.log(len(vc), 2) if len(vc) > 1 else 0.0
    return float(ent / max_ent) if max_ent > 0 else 0.0


def distribution_dict(df: pd.DataFrame, col: str, top_n: int = 10) -> Dict[str, int]:
    """Return the most common categorical values and their counts."""
    if col not in df.columns or len(df) == 0:
        return {}
    vc = df[col].dropna().astype(str).value_counts().head(top_n)
    return {str(k): int(v) for k, v in vc.items()}


def missing_fields_from_df(df: pd.DataFrame, expected_cols: List[str]) -> List[str]:
    """Return expected column names that are absent from a dataframe."""
    missing = [c for c in expected_cols if c not in df.columns]
    return missing


def missing_value_rate(df: pd.DataFrame, cols: List[str]) -> Optional[float]:
    """Return the mean missing-value rate across available columns."""
    present = [c for c in cols if c in df.columns]
    if not present or len(df) == 0:
        return None
    return float(df[present].isna().mean().mean())


def query_value(profile: Dict[str, Any], *paths: str) -> Any:
    """Resolve the first available dotted-path value from a query profile.
    
    Each supplied path is traversed defensively through nested dictionaries. This
    supports compatibility with profile fields that may have moved between schema
    versions."""
    for path in paths:
        cur: Any = profile
        ok = True
        for part in path.split("."):
            if isinstance(cur, dict) and part in cur:
                cur = cur[part]
            else:
                ok = False
                break
        if ok:
            return cur
    return None


def add_metric(rows: List[Dict[str, Any]], pool_name: str, category: str, name: str, value: Any, unit: str, explanation: str, missing_fields: Optional[List[str]] = None) -> None:
    """Append one normalised metric record to the metric-row collection."""
    rows.append({
        "pool_name": pool_name,
        "metric_category": category,
        "metric_name": name,
        "metric_value": value,
        "metric_unit": unit,
        "explanation": explanation,
        "missing_fields": ",".join(missing_fields or []),
    })


def load_pools(pool_dir: Path) -> Tuple[Dict[str, pd.DataFrame], Dict[str, Any]]:
    """Load all configured candidate pools and the optional pool summary.
    
    Missing pool files are represented by empty dataframes so downstream evidence
    generation can continue and report incomplete evidence explicitly."""
    pools: Dict[str, pd.DataFrame] = {}
    for pool_name, filename in POOL_FILES.items():
        path = pool_dir / filename
        if not path.exists():
            pools[pool_name] = pd.DataFrame()
            continue
        pools[pool_name] = pd.read_csv(path)
    summary_path = pool_dir / "candidate_pool_summary.json"
    summary = read_json(summary_path) if summary_path.exists() else {}
    return pools, summary


def pool_metrics(pool_name: str, df: pd.DataFrame, query_profile: Dict[str, Any]) -> Tuple[Dict[str, Any], List[Dict[str, Any]], List[Dict[str, Any]]]:
    """Calculate descriptive evidence metrics for one candidate pool.
    
    The returned structures contain the pool-level summary, flattened metric rows
    and missing-data diagnostics. Calculations cover chemistry/family similarity,
    symmetry, stability, metadata, diversity and bridge-support inputs.
    
    This function generates evidence only; it does not assign a final structural
    context role."""
    metric_rows: List[Dict[str, Any]] = []
    missing_rows: List[Dict[str, Any]] = []

    expected_missing = missing_fields_from_df(df, REQUIRED_POOL_COLUMNS)
    if len(df) == 0:
        base = {
            "pool_name": pool_name,
            "n_candidates": 0,
            "empty_pool": True,
            "missing_required_columns": expected_missing,
        }
        add_metric(metric_rows, pool_name, "pool", "n_candidates", 0, "count", "Number of rows in this candidate pool.", expected_missing)
        return base, metric_rows, [{
            "pool_name": pool_name,
            "field": "__pool__",
            "missing_count": None,
            "missing_rate": None,
            "note": "Pool is empty or file missing.",
        }]

    # Record missing column-level diagnostics.
    for col in REQUIRED_POOL_COLUMNS:
        if col not in df.columns:
            missing_rows.append({
                "pool_name": pool_name,
                "field": col,
                "missing_count": len(df),
                "missing_rate": 1.0,
                "note": "Required/recommended column absent from pool CSV.",
            })
        else:
            miss = int(df[col].isna().sum())
            missing_rows.append({
                "pool_name": pool_name,
                "field": col,
                "missing_count": miss,
                "missing_rate": float(miss / len(df)) if len(df) else None,
                "note": "Column present.",
            })

    q_identity = query_profile.get("identity", {})
    q_composition = query_profile.get("composition", {})
    q_struct = query_profile.get("structural_metadata", {})
    q_physical = query_profile.get("physical", {}).get("inputs", {})

    q_chemical_system = q_composition.get("chemical_system") or query_value(query_profile, "candidate_pool_inputs.chemical_key")
    q_family = q_composition.get("composition_family") or query_value(query_profile, "candidate_pool_inputs.family_key")
    family_class = query_profile.get("family_classification", {}) if isinstance(query_profile.get("family_classification"), dict) else {}
    q_material_family = (
        family_class.get("material_family")
        or q_struct.get("material_family")
        or query_value(query_profile, "candidate_pool_inputs.family_key")
        or q_family
    )
    q_formula_family = family_class.get("formula_family") or query_value(query_profile, "candidate_pool_inputs.formula_family_key")
    q_prototype_family = family_class.get("prototype_family") or query_value(query_profile, "candidate_pool_inputs.prototype_family_key")
    q_structure_variant = family_class.get("structure_variant") or query_value(query_profile, "candidate_pool_inputs.structure_variant_key")
    q_spacegroup = safe_float(q_struct.get("spacegroup_number") or query_value(query_profile, "candidate_pool_inputs.symmetry_key"))
    q_crystal = safe_float(q_struct.get("crystal_system_code"))
    q_ehull = safe_float(q_physical.get("energy_above_hull"))

    # Basic pool metrics
    n = int(len(df))
    duplicate_candidate_count = int(df["candidate_jid"].duplicated().sum()) if "candidate_jid" in df.columns else None
    duplicate_formula_count = int(df["formula"].duplicated().sum()) if "formula" in df.columns else None

    base: Dict[str, Any] = {
        "pool_name": pool_name,
        "n_candidates": n,
        "empty_pool": False,
        "duplicate_candidate_count": duplicate_candidate_count,
        "duplicate_formula_count": duplicate_formula_count,
        "missing_required_columns": expected_missing,
    }

    add_metric(metric_rows, pool_name, "pool", "n_candidates", n, "count", "Number of rows in this candidate pool.", expected_missing)
    add_metric(metric_rows, pool_name, "pool", "duplicate_candidate_count", duplicate_candidate_count, "count", "Repeated candidate_jid rows inside this pool.", ["candidate_jid"] if "candidate_jid" not in df.columns else [])
    add_metric(metric_rows, pool_name, "pool", "duplicate_formula_count", duplicate_formula_count, "count", "Repeated formula rows inside this pool.", ["formula"] if "formula" not in df.columns else [])
    add_metric(metric_rows, pool_name, "pool", "missing_value_rate_required_columns", missing_value_rate(df, REQUIRED_POOL_COLUMNS), "fraction", "Average missing-value rate across required/recommended Phase 3 columns.", expected_missing)

    # Chemistry metrics.
    chem_metrics = {
        "same_chemical_system_rate": rate_bool(df, "same_chemical_system"),
        "same_composition_family_rate": rate_bool(df, "same_composition_family"),
        "same_material_family_rate": rate_match_or_bool(df, "same_material_family", "material_family", q_material_family),
        "same_formula_family_rate": rate_match_or_bool(df, "same_formula_family", "formula_family", q_formula_family),
        "same_prototype_family_rate": rate_match_or_bool(df, "same_prototype_family", "prototype_family", q_prototype_family),
        "same_structure_variant_rate": rate_match_or_bool(df, "same_structure_variant", "structure_variant", q_structure_variant),
        "mean_element_overlap_count": mean_numeric(df, "element_overlap_count"),
        "mean_element_overlap_fraction_query": mean_numeric(df, "element_overlap_fraction_query"),
        "chemical_system_count": unique_count(df, "chemical_system"),
        "composition_family_count": unique_count(df, "composition_family"),
        "material_family_count": unique_count(df, "material_family"),
        "formula_family_count": unique_count(df, "formula_family"),
        "prototype_family_count": unique_count(df, "prototype_family"),
        "structure_variant_count": unique_count(df, "structure_variant"),
        "composition_family_entropy": normalized_entropy(df, "composition_family"),
        "material_family_entropy": normalized_entropy(df, "material_family"),
        "formula_family_entropy": normalized_entropy(df, "formula_family"),
        "prototype_family_entropy": normalized_entropy(df, "prototype_family"),
        "structure_variant_entropy": normalized_entropy(df, "structure_variant"),
        "dominant_chemical_system": most_common_value(df, "chemical_system"),
        "dominant_composition_family": most_common_value(df, "composition_family"),
        "dominant_material_family": most_common_value(df, "material_family"),
        "dominant_formula_family": most_common_value(df, "formula_family"),
        "dominant_prototype_family": most_common_value(df, "prototype_family"),
        "dominant_structure_variant": most_common_value(df, "structure_variant"),
    }
    base.update(chem_metrics)

    add_metric(metric_rows, pool_name, "chemistry", "same_chemical_system_rate", chem_metrics["same_chemical_system_rate"], "fraction", f"Fraction of candidates with the same chemical system as query ({q_chemical_system}).", ["same_chemical_system"] if "same_chemical_system" not in df.columns else [])
    add_metric(metric_rows, pool_name, "chemistry", "same_composition_family_rate", chem_metrics["same_composition_family_rate"], "fraction", f"Fraction of candidates with the same composition family as query ({q_family}).", ["same_composition_family"] if "same_composition_family" not in df.columns else [])
    add_metric(metric_rows, pool_name, "chemistry", "same_material_family_rate", chem_metrics["same_material_family_rate"], "fraction", f"Fraction of candidates with the same broad material family as query ({q_material_family}).", ["same_material_family", "material_family"] if ("same_material_family" not in df.columns and "material_family" not in df.columns) else [])
    add_metric(metric_rows, pool_name, "chemistry", "same_formula_family_rate", chem_metrics["same_formula_family_rate"], "fraction", f"Fraction of candidates with the same formula family as query ({q_formula_family}).", ["same_formula_family", "formula_family"] if ("same_formula_family" not in df.columns and "formula_family" not in df.columns) else [])
    add_metric(metric_rows, pool_name, "chemistry", "same_prototype_family_rate", chem_metrics["same_prototype_family_rate"], "fraction", f"Fraction of candidates with the same prototype family as query ({q_prototype_family}).", ["same_prototype_family", "prototype_family"] if ("same_prototype_family" not in df.columns and "prototype_family" not in df.columns) else [])
    add_metric(metric_rows, pool_name, "chemistry", "same_structure_variant_rate", chem_metrics["same_structure_variant_rate"], "fraction", f"Fraction of candidates with the same structure variant as query ({q_structure_variant}).", ["same_structure_variant", "structure_variant"] if ("same_structure_variant" not in df.columns and "structure_variant" not in df.columns) else [])
    add_metric(metric_rows, pool_name, "chemistry", "mean_element_overlap_fraction_query", chem_metrics["mean_element_overlap_fraction_query"], "fraction", "Average fraction of query elements present in candidates.", ["element_overlap_fraction_query"] if "element_overlap_fraction_query" not in df.columns else [])
    add_metric(metric_rows, pool_name, "chemistry", "composition_family_entropy", chem_metrics["composition_family_entropy"], "0-1", "Normalised entropy of composition families. Low = concentrated family; high = diverse families.", ["composition_family"] if "composition_family" not in df.columns else [])
    add_metric(metric_rows, pool_name, "chemistry", "material_family_entropy", chem_metrics["material_family_entropy"], "0-1", "Normalised entropy of broad material families. Low = concentrated family; high = diverse families.", ["material_family"] if "material_family" not in df.columns else [])
    add_metric(metric_rows, pool_name, "chemistry", "formula_family_entropy", chem_metrics["formula_family_entropy"], "0-1", "Normalised entropy of formula families. Low = concentrated stoichiometric family; high = diverse families.", ["formula_family"] if "formula_family" not in df.columns else [])
    add_metric(metric_rows, pool_name, "chemistry", "prototype_family_entropy", chem_metrics["prototype_family_entropy"], "0-1", "Normalised entropy of prototype families. Low = concentrated prototype context; high = diverse prototype contexts.", ["prototype_family"] if "prototype_family" not in df.columns else [])
    add_metric(metric_rows, pool_name, "chemistry", "structure_variant_entropy", chem_metrics["structure_variant_entropy"], "0-1", "Normalised entropy of structure variants. Low = concentrated variant; high = variant-diverse.", ["structure_variant"] if "structure_variant" not in df.columns else [])

    # Metadata metrics.
    meta_metrics = {
        "material_type_count": unique_count(df, "material_type"),
        "dataset_kind_count": unique_count(df, "dataset_kind"),
        "dominant_material_type": most_common_value(df, "material_type"),
        "dominant_dataset_kind": most_common_value(df, "dataset_kind"),
        "selection_reason_count": unique_count(df, "selection_reason"),
        "selection_reason_distribution": distribution_dict(df, "selection_reason", top_n=12),
        "mean_selection_score": mean_numeric(df, "selection_score"),
        "median_selection_score": median_numeric(df, "selection_score"),
    }
    base.update(meta_metrics)

    add_metric(metric_rows, pool_name, "metadata", "material_type_count", meta_metrics["material_type_count"], "count", "Number of distinct material_type values in pool.", ["material_type"] if "material_type" not in df.columns else [])
    add_metric(metric_rows, pool_name, "metadata", "dataset_kind_count", meta_metrics["dataset_kind_count"], "count", "Number of distinct dataset_kind values in pool.", ["dataset_kind"] if "dataset_kind" not in df.columns else [])
    add_metric(metric_rows, pool_name, "metadata", "mean_selection_score", meta_metrics["mean_selection_score"], "score", "Average Phase 2 cheap selection score for candidates in this pool.", ["selection_score"] if "selection_score" not in df.columns else [])

    # Symmetry metrics.
    sym_metrics = {
        "same_spacegroup_rate": rate_bool(df, "symmetry_match"),
        "mean_symmetry_distance": mean_numeric(df, "symmetry_distance"),
        "median_symmetry_distance": median_numeric(df, "symmetry_distance"),
        "spacegroup_count": unique_count(df, "spacegroup_number"),
        "crystal_system_count": unique_count(df, "crystal_system_code"),
        "spacegroup_entropy": normalized_entropy(df, "spacegroup_number"),
        "crystal_system_entropy": normalized_entropy(df, "crystal_system_code"),
        "dominant_spacegroup_number": most_common_value(df, "spacegroup_number"),
        "dominant_spacegroup_symbol": most_common_value(df, "spacegroup_symbol"),
        "dominant_crystal_system_code": most_common_value(df, "crystal_system_code"),
    }

    # If symmetry_match was not available, derive from spacegroup.
    if sym_metrics["same_spacegroup_rate"] is None and "spacegroup_number" in df.columns and q_spacegroup is not None:
        sg = pd.to_numeric(df["spacegroup_number"], errors="coerce")
        valid = sg.dropna()
        sym_metrics["same_spacegroup_rate"] = float((valid == q_spacegroup).mean()) if len(valid) else None

    if "crystal_system_code" in df.columns and q_crystal is not None:
        cs = pd.to_numeric(df["crystal_system_code"], errors="coerce")
        valid = cs.dropna()
        sym_metrics["same_crystal_system_rate"] = float((valid == q_crystal).mean()) if len(valid) else None
    else:
        sym_metrics["same_crystal_system_rate"] = None

    base.update(sym_metrics)

    add_metric(metric_rows, pool_name, "symmetry", "same_spacegroup_rate", sym_metrics["same_spacegroup_rate"], "fraction", f"Fraction of candidates matching query space group ({q_spacegroup}).", ["symmetry_match", "spacegroup_number"] if ("symmetry_match" not in df.columns and "spacegroup_number" not in df.columns) else [])
    add_metric(metric_rows, pool_name, "symmetry", "same_crystal_system_rate", sym_metrics["same_crystal_system_rate"], "fraction", f"Fraction of candidates matching query crystal system code ({q_crystal}).", ["crystal_system_code"] if "crystal_system_code" not in df.columns else [])
    add_metric(metric_rows, pool_name, "symmetry", "mean_symmetry_distance", sym_metrics["mean_symmetry_distance"], "absolute_difference", "Average absolute space-group distance from query, as supplied by Phase 2.", ["symmetry_distance"] if "symmetry_distance" not in df.columns else [])
    add_metric(metric_rows, pool_name, "symmetry", "spacegroup_entropy", sym_metrics["spacegroup_entropy"], "0-1", "Normalised entropy of space-group distribution. High values indicate diverse symmetry.", ["spacegroup_number"] if "spacegroup_number" not in df.columns else [])
    add_metric(metric_rows, pool_name, "symmetry", "crystal_system_entropy", sym_metrics["crystal_system_entropy"], "0-1", "Normalised entropy of crystal-system distribution.", ["crystal_system_code"] if "crystal_system_code" not in df.columns else [])

    # Stability metrics.
    ehull = pd.to_numeric(df["energy_above_hull"], errors="coerce") if "energy_above_hull" in df.columns else pd.Series(dtype=float)
    stable_threshold = 0.1
    stability_metrics = {
        "mean_energy_above_hull": mean_numeric(df, "energy_above_hull"),
        "median_energy_above_hull": median_numeric(df, "energy_above_hull"),
        "std_energy_above_hull": std_numeric(df, "energy_above_hull"),
        "stable_fraction_ehull_le_0_1": float((ehull.dropna() <= stable_threshold).mean()) if len(ehull.dropna()) else None,
        "zero_hull_fraction": float((ehull.dropna() == 0).mean()) if len(ehull.dropna()) else None,
        "known_synthesized_rate": rate_bool(df, "known_synthesized"),
        "stability_label_count": unique_count(df, "stability_label"),
        "dominant_stability_label": most_common_value(df, "stability_label"),
        "formation_energy_mean": mean_numeric(df, "formation_energy"),
        "formation_energy_peratom_mean": mean_numeric(df, "formation_energy_peratom"),
        "energy_above_hull_missing_rate": 1.0 - (non_missing_rate(df, "energy_above_hull") or 0.0) if "energy_above_hull" in df.columns else 1.0,
        "known_synthesized_missing_rate": 1.0 - (non_missing_rate(df, "known_synthesized") or 0.0) if "known_synthesized" in df.columns else 1.0,
    }
    base.update(stability_metrics)

    add_metric(metric_rows, pool_name, "stability", "mean_energy_above_hull", stability_metrics["mean_energy_above_hull"], "eV", f"Average energy above hull in candidate pool. Query value is {q_ehull}.", ["energy_above_hull"] if "energy_above_hull" not in df.columns else [])
    add_metric(metric_rows, pool_name, "stability", "stable_fraction_ehull_le_0_1", stability_metrics["stable_fraction_ehull_le_0_1"], "fraction", "Fraction of candidates with energy_above_hull <= 0.1 eV.", ["energy_above_hull"] if "energy_above_hull" not in df.columns else [])
    add_metric(metric_rows, pool_name, "stability", "zero_hull_fraction", stability_metrics["zero_hull_fraction"], "fraction", "Fraction of candidates exactly on the hull according to available metadata.", ["energy_above_hull"] if "energy_above_hull" not in df.columns else [])
    add_metric(metric_rows, pool_name, "stability", "known_synthesized_rate", stability_metrics["known_synthesized_rate"], "fraction", "Fraction of candidates marked known_synthesized=True.", ["known_synthesized"] if "known_synthesized" not in df.columns else [])
    add_metric(metric_rows, pool_name, "stability", "energy_above_hull_missing_rate", stability_metrics["energy_above_hull_missing_rate"], "fraction", "Missing-value rate for energy_above_hull.", ["energy_above_hull"] if "energy_above_hull" not in df.columns else [])

    # First-class bridge-support inputs.  These remain cheap, pool-level, and
    # backwards-compatible: they use only existing Phase 2 columns when present.
    # The role prior engine can consume these directly instead of trying to
    # infer bridge from "not hub" and "not boundary".  Apparently bridge
    # evidence enjoys being treated as a real concept.
    symmetry_similarity = mean_available([
        sym_metrics.get("same_spacegroup_rate"),
        sym_metrics.get("same_crystal_system_rate"),
        1.0 - clip01((sym_metrics.get("mean_symmetry_distance") or 0.0) / 100.0) if sym_metrics.get("mean_symmetry_distance") is not None else None,
    ])
    family_similarity = mean_available([
        chem_metrics.get("same_composition_family_rate"),
        chem_metrics.get("same_material_family_rate"),
        chem_metrics.get("same_formula_family_rate"),
        chem_metrics.get("same_prototype_family_rate"),
        chem_metrics.get("same_structure_variant_rate"),
    ])
    chemical_similarity = mean_available([
        chem_metrics.get("same_chemical_system_rate"),
        chem_metrics.get("mean_element_overlap_fraction_query"),
        chem_metrics.get("same_composition_family_rate"),
    ])
    structural_metadata_similarity = mean_available([
        chem_metrics.get("same_prototype_family_rate"),
        chem_metrics.get("same_structure_variant_rate"),
        symmetry_similarity,
    ])
    query_similarity_score = mean_available([
        chemical_similarity,
        family_similarity,
        structural_metadata_similarity,
        stability_metrics.get("stable_fraction_ehull_le_0_1"),
    ])
    pool_diversity_score = mean_available([
        chem_metrics.get("composition_family_entropy"),
        chem_metrics.get("material_family_entropy"),
        chem_metrics.get("formula_family_entropy"),
        chem_metrics.get("prototype_family_entropy"),
        chem_metrics.get("structure_variant_entropy"),
        sym_metrics.get("spacegroup_entropy"),
        sym_metrics.get("crystal_system_entropy"),
    ])
    structural_regime_diversity_score = mean_available([
        chem_metrics.get("prototype_family_entropy"),
        chem_metrics.get("structure_variant_entropy"),
        sym_metrics.get("spacegroup_entropy"),
        sym_metrics.get("crystal_system_entropy"),
    ])

    bridge_input_metrics = {
        "chemical_similarity_score": chemical_similarity,
        "family_similarity_score": family_similarity,
        "symmetry_similarity_score": symmetry_similarity,
        "structural_metadata_similarity_score": structural_metadata_similarity,
        "query_similarity_score": query_similarity_score,
        "pool_diversity_score": pool_diversity_score,
        "structural_regime_diversity_score": structural_regime_diversity_score,
    }
    base.update(bridge_input_metrics)

    for metric_name, metric_value in bridge_input_metrics.items():
        add_metric(
            metric_rows,
            pool_name,
            "bridge_inputs",
            metric_name,
            metric_value,
            "0-1",
            "Derived cheap pool-level input for bridge-specific evidence and downstream role priors.",
            [],
        )

    return base, metric_rows, missing_rows


def overlap_summary(pools: Dict[str, pd.DataFrame]) -> Dict[str, Any]:
    """Summarise candidate overlap between the configured pools."""
    ids = {
        name: set(df["candidate_jid"].dropna().astype(str).tolist()) if "candidate_jid" in df.columns else set()
        for name, df in pools.items()
    }
    pairwise: Dict[str, int] = {}
    names = list(ids.keys())
    for i, a in enumerate(names):
        for b in names[i+1:]:
            pairwise[f"{a}__{b}"] = len(ids[a] & ids[b])
    all_counts = Counter()
    for s in ids.values():
        all_counts.update(s)
    return {
        "pairwise_candidate_overlap_counts": pairwise,
        "unique_candidate_count_across_all_pools": int(len(all_counts)),
        "candidate_ids_in_multiple_pools": int(sum(1 for _, c in all_counts.items() if c > 1)),
    }


def _normalise_scalar(value: Any) -> Any:
    """Convert pandas/numpy scalar values to stable JSON-safe Python values."""
    if value is None:
        return None
    try:
        if pd.isna(value):
            return None
    except Exception:
        pass
    if isinstance(value, bool):
        return bool(value)
    if isinstance(value, int):
        return int(value)
    if isinstance(value, float):
        return None if math.isnan(value) else float(value)
    # Preserve integer-looking and float-looking numpy scalars without importing numpy.
    try:
        item = value.item()  # type: ignore[attr-defined]
        if item is not value:
            return _normalise_scalar(item)
    except Exception:
        pass
    return str(value)


def _normalise_bool(value: Any) -> Optional[bool]:
    """Normalise a scalar value to ``True``, ``False`` or ``None``."""
    if value is None:
        return None
    try:
        if pd.isna(value):
            return None
    except Exception:
        pass
    if isinstance(value, bool):
        return bool(value)
    s = str(value).strip().lower()
    if s in {"true", "1", "yes", "y"}:
        return True
    if s in {"false", "0", "no", "n"}:
        return False
    return None


def _numeric_distribution(df: pd.DataFrame, col: str) -> Dict[str, Any]:
    """Compact descriptive statistics for one numeric neighbour attribute."""
    if col not in df.columns:
        return {
            "available": False,
            "count": 0,
            "missing_count": int(len(df)),
            "mean": None,
            "median": None,
            "std": None,
            "min": None,
            "max": None,
        }
    vals = pd.to_numeric(df[col], errors="coerce")
    valid = vals.dropna()
    return {
        "available": bool(len(valid) > 0),
        "count": int(len(valid)),
        "missing_count": int(vals.isna().sum()),
        "mean": float(valid.mean()) if len(valid) else None,
        "median": float(valid.median()) if len(valid) else None,
        "std": float(valid.std()) if len(valid) > 1 else None,
        "min": float(valid.min()) if len(valid) else None,
        "max": float(valid.max()) if len(valid) else None,
    }


def _categorical_distribution(df: pd.DataFrame, col: str) -> Dict[str, Any]:
    """Full count and fraction distribution for one categorical neighbour attribute."""
    if col not in df.columns:
        return {
            "available": False,
            "non_missing_count": 0,
            "missing_count": int(len(df)),
            "unique_count": 0,
            "dominant_value": None,
            "dominant_fraction": None,
            "counts": {},
            "fractions": {},
        }
    series = df[col]
    non_missing = series.dropna().astype(str)
    vc = non_missing.value_counts(dropna=True)
    total = int(vc.sum())
    counts = {str(k): int(v) for k, v in vc.items()}
    fractions = {str(k): float(v / total) for k, v in vc.items()} if total else {}
    dominant_value = str(vc.index[0]) if not vc.empty else None
    dominant_fraction = float(vc.iloc[0] / total) if total and not vc.empty else None
    return {
        "available": bool(total > 0),
        "non_missing_count": total,
        "missing_count": int(series.isna().sum()),
        "unique_count": int(len(vc)),
        "dominant_value": dominant_value,
        "dominant_fraction": dominant_fraction,
        "counts": counts,
        "fractions": fractions,
    }


def _ordered_pool_frame(df: pd.DataFrame) -> pd.DataFrame:
    """Return a deterministic pool order, preferring rank then selection score."""
    if df.empty:
        return df.copy()
    out = df.copy()
    out["__original_order"] = range(len(out))
    sort_cols: List[str] = []
    ascending: List[bool] = []
    if "rank_in_pool" in out.columns:
        out["__rank_numeric"] = pd.to_numeric(out["rank_in_pool"], errors="coerce")
        sort_cols.append("__rank_numeric")
        ascending.append(True)
    if "selection_score" in out.columns:
        out["__selection_numeric"] = pd.to_numeric(out["selection_score"], errors="coerce")
        sort_cols.append("__selection_numeric")
        ascending.append(False)
    sort_cols.append("__original_order")
    ascending.append(True)
    return out.sort_values(sort_cols, ascending=ascending, na_position="last", kind="mergesort")


def _reference_neighbour_record(row: pd.Series, pool_name: str) -> Dict[str, Any]:
    """Create one compact, stable reference-neighbour record from a pool row."""
    # Keep the per-neighbour record intentionally compact. Aggregate chemistry,
    # stability and missingness information is retained separately below.
    scalar_fields = [
        "candidate_jid",
        "formula",
        "chemical_system",
        "composition_family",
        "material_family",
        "formula_family",
        "prototype_family",
        "structure_variant",
        "spacegroup_number",
        "spacegroup_symbol",
        "crystal_system_code",
        "selection_score",
        "rank_in_pool",
        "element_overlap_fraction_query",
        "symmetry_distance",
    ]
    bool_fields = [
        "same_chemical_system",
        "same_composition_family",
        "same_material_family",
        "same_formula_family",
        "same_prototype_family",
        "same_structure_variant",
        "symmetry_match",
    ]
    record: Dict[str, Any] = {"pool_name": pool_name}
    for field in scalar_fields:
        if field in row.index:
            record[field] = _normalise_scalar(row.get(field))
    for field in bool_fields:
        if field in row.index:
            record[field] = _normalise_bool(row.get(field))
    return record



